<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\ValueObject\Accessor\UserGroupMembershipGroupsAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserGroupMembershipGroupsAccessor trait.
 *
 * Covers null default, string/VO assignment via withGroups,
 * getGroups/groups accessors, and isGroupsChanged with/without original.
 */
class UserGroupMembershipGroupsAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withGroups creates a new instance with the Groups set
     * from a string value, and getGroups returns the primitive string.
     */
    public function testWithGroupsFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserGroupMembershipGroupsAccessorUnitTest();

        // Act
        $result = $holder->withGroups('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getGroups());
    }
    /**
     * Asserts that withgroups has access to the value object
     * from a string value, and getGroups returns the primitive string.
     */
    public function testWithGroupsFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserGroupMembershipGroupsAccessorUnitTest();

        // Act
        $result = $holder->withGroups('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->groups()->value());
    }
    public function testChangedGroups(): void
    {
        // Arrange
        $holder = new ImplWithUserGroupMembershipGroupsAccessorUnitTest();
        $original = $holder->withGroups('one');
        $same = $holder->withGroups('one');
        $modified = $holder->withGroups('other');

        // Act
        $unchanged = $holder->isGroupsChanged();
        $withSame = $original->isGroupsChanged($same);
        $withDiferent = $original->isGroupsChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserGroupMembershipGroupsAccessorUnitTest
{
    use UserGroupMembershipGroupsAccessor;
}
